D={
80338:("Will","**Will** + verbo base = futuro/promessa. *I will marry you. They will dance.* Forma curta: **I'll, she'll**. Negativo: **won't**.",[("I {{will}} love you.","Eu vou te amar."),("They {{will}} dance.","Eles vão dançar."),("She{{'ll}} wear a dress.","Ela vai usar um vestido."),("We {{won't}} be late.","Não vamos nos atrasar.")],"Negativa de will:",["won't","willn't","don't will"],0,"Will not = won't."),
910042:("Best wishes","Parabéns: **Congratulations! Best wishes! Happy anniversary!** Com cartão: **Congratulations on…** *Congratulations on your wedding!*",[("{{Congratulations}}!","Parabéns!"),("{{Best wishes}}!","Os melhores votos!"),("Congratulations {{on}} your wedding.","Parabéns pelo casamento."),("Open the greeting card.","Abra o cartão.")],"“Parabéns pelo casamento”:",["Congratulations on your wedding!","Congratulations for wedding.","Congratulation wedding!"],0,"Congratulations on…"),
80339:("Trick or treat","Halloween: **Trick or treat!** = doces ou travessuras. Fantasia: **I'm wearing a costume. I'm a witch.** *Wear a costume.*",[("{{Trick or treat}}!","Doces ou travessuras!"),("I'm {{a witch}}.","Sou uma bruxa."),("I {{wear}} a costume.","Uso uma fantasia."),("Thanks for the candy!","Obrigado pelos doces!")],"Quem usa fantasia:",["wear a costume","do costume","put at costume"],0,"wear."),
80340:("Some e any","**Some** em afirmativas e ofertas: **Would you like some pie?** **Any** em negativas e perguntas. *Is there any turkey?*",[("Would you like {{some}} pie?","Quer um pouco de torta?"),("Is there {{any}} corn?","Tem milho?"),("I don't want {{any}} potatoes.","Não quero batatas."),("We have some turkey.","Temos peru.")],"Em oferta use…",["some","any","a"],0,"Oferta: some."),
80341:("Contagem","Contagem regressiva: **Ten, nine, eight… one! Happy New Year!** Numerais antes de 20 têm formas próprias.",[("{{Ten, nine, eight}}…","Dez, nove, oito…"),("{{Three, two, one}}!","Três, dois, um!"),("{{Happy New Year}}!","Feliz Ano Novo!"),("Midnight!","Meia-noite!")],"“Feliz Ano Novo”:",["Happy New Year!","Good New Year!","Nice year new!"],0,"Happy New Year."),
80342:("Like, love","**Like** = gostar. **Love** = amar/adorar. *I like Tom. I love chocolate.* **Love** para coisas: *I love it!*",[("I {{like}} him.","Gosto dele."),("I {{love}} chocolate.","Adoro chocolate."),("She {{loves}} him.","Ela o ama."),("A card with a heart.","Um cartão com um coração.")],"Mais forte que like:",["love","know","meet"],0,"Love."),
910043:("How are you really?","Cumprimentos: **How are you? — Fine, thanks. / Alright. / Swamped!** Resposta sincera: **I'm swamped** = estou atolado.",[("How are you {{really}}?","Como você está de verdade?"),("I'm {{alright}}.","Estou bem."),("I'm {{swamped}}.","Estou atolado."),("I'm {{fantastic}}!","Estou ótimo!")],"“Estou atolado de trabalho”:",["I'm swamped.","I'm swap.","I swamped."],0,"Swamped."),
80343:("Festival: contínuo","Presente contínuo: **The band is playing. The crowd is dancing.** **be + -ing**. *What's happening?*",[("The band {{is playing}}.","A banda está tocando."),("The crowd {{is dancing}}.","A multidão está dançando."),("They {{are riding}} the rides.","Eles estão nos brinquedos."),("What's happening?","O que está acontecendo?")],"Complete: “The kids ___ a parade.” (watch)",["watch","are watching","watches"],1,"be + -ing."),
80344:("Pedir esclarecimento","Se não entender: **Sorry, can you repeat? What does … mean? How do you spell it?** *Can you say it slowly?*",[("{{Sorry, can you repeat}}?","Desculpe, pode repetir?"),("{{What does}} accent {{mean}}?","O que significa accent?"),("{{How do you spell}} it?","Como se soletra?"),("Slowly, please.","Devagar, por favor.")],"Para pedir repetição:",["Can you repeat?","You repeat can?","Say again me."],0,"Can you repeat?"),
910044:("No worries!","Respostas informais: **No problem. No worries. No big deal. Never mind.** Para agradecimento: **No worries!** = de nada.",[("{{No worries}}!","Sem problemas!"),("{{No big deal}}.","Não foi nada."),("{{Never mind}}.","Deixa pra lá."),("Don't worry about it.","Não se preocupe com isso.")],"Resposta a “Sorry!”:",["No worries!","Sorry too.","Please."],0,"No worries."),
80345:("Well, you know…","Pausas na fala: **Well…, You know…, I mean…** dão tempo para pensar. *Well, I think it's nice.*",[("{{Well}}, I think it's nice.","Bem, acho bonito."),("{{You know}}, it's a secret.","Sabe, é um segredo."),("{{I mean}}, it's beautiful.","Quer dizer, é bonito."),("What's your opinion?","Qual sua opinião?")],"Uma pausa comum:",["Well…","Please…","Thank…"],0,"Well…"),
80346:("Gonna, wanna, gotta","Fala rápida: **gonna = going to**, **wanna = want to**, **gotta = got to**. *I'm gonna visit. I wanna go.* Na escrita formal, evite.",[("I'm {{gonna}} visit her.","Vou visitá-la."),("I {{wanna}} drink tea.","Quero tomar chá."),("I {{gotta}} go.","Tenho que ir."),("Yeah, nope.","É, não.")],"Gonna significa…",["going to","got no","good now"],0,"going to."),
910045:("Sounds good!","Aceitar: **Sounds good! It's a deal! Works for me. Fair enough.** Para recusar: **Maybe later.** *Let's shake on it.*",[("{{Sounds good}}!","Parece bom!"),("{{It's a deal}}!","Fechado!"),("{{Works for me}}.","Para mim está bom."),("{{Fair enough}}.","Justo.")],"“Fechado!”:",["It's a deal!","It's a sale!","Deal it."],0,"It's a deal."),
80347:("Papo rápido","Elevador: **How's it going? — Not bad. Nice weather! Have a good weekend!** Frases curtas e simpáticas.",[("{{How's it going}}?","Como vai?"),("{{Not bad}}.","Nada mal."),("{{Nice weather}}, isn't it?","Tempo bom, né?"),("{{Have a good weekend}}!","Bom fim de semana!")],"Resposta a How's it going?",["Not bad.","Yes, please.","I'm welcome."],0,"Not bad."),
910046:("Gonna, wanna, gotta","Contrações da fala: **gonna, wanna, gotta, kinda.** Soam informais. *I'm gonna go.* Em provas e e-mails, use **going to / want to**.",[("I'm {{gonna}} go.","Eu vou."),("{{Wanna}} come?","Quer vir?"),("I {{gotta}} run.","Tenho que correr."),("It's casual speech.","É fala informal.")],"Gotta significa…",["got to","going","want"],0,"Got to."),
80348:("Profissões: presente","Apresentar-se: **I'm a baker. I work at a bakery. I make bread.** Presente simples + **a/an**.",[("I'm {{a baker}}."," Sou padeiro."),("I {{work}} at a bakery.","Trabalho em uma padaria."),("I {{make}} bread.","Faço pão."),("She's {{an engineer}}.","Ela é engenheira.")],"“Sou enfermeiro”:",["I'm a nurse.","I'm nurse.","I nurse am."],0,"I'm a + profissão."),
910047:("Hit the books","**Hit the books** = estudar muito (idioma). **All-nighter** = virar a noite estudando. *I'm going to hit the books.*",[("I {{hit the books}}.","Eu vou estudar pesado."),("I pull {{an all-nighter}}.","Viro a noite."),("I have {{finals}}.","Tenho provas finais."),("Use flashcards.","Use cartões de estudo.")],"O que significa hit the books?",["estudar muito","bater em livros","comprar livros"],0,"Estudar muito."),
80349:("Despedidas","Despedir: **Goodbye! See you tomorrow! Take care!** *For now* = por ora. **See you** + quando.",[("{{Goodbye for now}}!","Tchau por ora!"),("{{See you tomorrow}}!","Até amanhã!"),("{{Take care}}!","Se cuide!"),("Thank you for the visit.","Obrigado pela visita.")],"“Até amanhã”:",["See you tomorrow.","Look you tomorrow.","Meet tomorrow you."],0,"See you."),
910048:("Cost an arm and a leg","**Cost an arm and a leg** = custar os olhos da cara. **Cost** = custar. *It costs ten dollars.*",[("It {{costs an arm and a leg}}!","Custa os olhos da cara!"),("It {{costs}} ten dollars.","Custa dez dólares."),("Let's {{save}} money.","Vamos economizar."),("It's on sale.","Está em promoção.")],"“Custar caro”:",["cost an arm and a leg","cost a hand","pay arm"],0,"Idioma."),
910049:("Keep in touch","**Keep in touch** = manter contato. **Drop a line** = mandar uma mensagem. *Let's keep in touch!*",[("{{Keep in touch}}!","Mantenha contato!"),("{{Drop me a line}}.","Me mande um recado."),("{{Send me}} your phone number.","Me envie seu telefone."),("Say hi to your family.","Mande um abraço à família.")],"“Manter contato”:",["keep in touch","hold touch","stay touch of"],0,"Keep in touch."),
910050:("See you around","Despedidas informais: **Bye! See you around! Take care! Safe trip!** *Bon voyage!* = boa viagem.",[("{{See you around}}!","A gente se vê!"),("{{Take care}}!","Se cuida!"),("{{Safe trip}}!","Boa viagem!"),("{{Bye}}!","Tchau!")],"“Boa viagem”:",["Safe trip!","Good road!","Fine travel!"],0,"Safe trip."),
80350:("Parabéns, A1!","Você concluiu o A1. **Revisão**: be, can, presente simples, plural, perguntas e negativas. **Cheers!** = saúde! *Cheers to A1!*",[("{{I am}} a student.","Sou estudante."),("{{I can}} speak English.","Falo inglês."),("{{I don't}} give up.","Não desisto."),("{{Cheers to A1}}!","Um brinde ao A1!")],"Qual frase é uma negativa?",["I don't give up.","I give up.","Do I give up?"],0,"Negativa: don't."),
}
